const UNKNOWN_BRAND: CreditCardBrand = {
  name: "",
  pattern: /^/,
  groups: [4, 4, 4, 4],
  lengths: [16],
  securityCodeLength: 3
};

/** Get the brand of a card number (its digits only). */
export const getCreditCardBrand = (digits: string): CreditCardBrand =>
  CREDIT_CARD_BRANDS.find(brand => brand.pattern.test(digits)) ?? UNKNOWN_BRAND;

const groupDigits = (digits: string, groups: number[]) => {
  const parts: string[] = [];
  let start = 0;
  for (const size of groups) {
    if (start >= digits.length) {
      break;
    }

    parts.push(digits.slice(start, (start += size)));
  }

  return parts.join(" ");
};

const isLuhnValid = (digits: string) => {
  let sum = 0;
  for (let index = 0; index < digits.length; index++) {
    // Every second digit from the right is doubled.
    let digit = Number(digits[digits.length - 1 - index]);
    if (index % 2 === 1) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
  }

  return sum % 10 === 0;
};

const toDigits = (value: unknown) => String(value ?? "").replace(/\D/g, "");

// The groups follow the brand of the digits typed so far, so an Amex number
// switches to 4-6-5 as soon as its "34"/"37" is entered.
const CARD_NUMBER_MASK: MaskitoOptions = {
  mask: ({ value }) => {
    const { groups, lengths } = getCreditCardBrand(toDigits(value));

    return [...groupDigits("0".repeat(Math.max(...lengths)), groups)].map(
      character => (character === " " ? " " : /\d/)
    );
  }
};

const EXPIRY_MASK: MaskitoOptions = {
  mask: [/\d/, /\d/, "/", /\d/, /\d/]
};

export type CreditCardPart = "number" | "expiry" | "securityCode" | "name";

export type CreditCardValues = Record<CreditCardPart, string>;

interface CreditCardPartRule {
  mask?: (brand: CreditCardBrand) => MaskitoOptions;
  /** The field's value from the displayed text. */
  parse?: (text: unknown) => string;
  /** The displayed text from the field's value. */
  format?: (value: unknown) => string;
  /** Whether enough has been typed to report an error before blur. */
  isComplete: (value: string, brand: CreditCardBrand) => boolean;
  /** Why a (non-empty) value is invalid, or `undefined` when it is valid. */
  getError: (value: string, brand: CreditCardBrand) => string | undefined;
  valueProps: Partial<GetProps<typeof Input.TextBox.Value>>;
  /**
   * Masks the value with `PasswordInput`, showing each typed character for
   * this many milliseconds before masking it.
   */
  passwordDelay?: number;
  end?: (brand: CreditCardBrand) => ReactNode;
}

interface CreditCardInputContextValue {
  values: CreditCardValues;
  setValue: (part: CreditCardPart, value: string) => void;
}

const EMPTY_VALUES: CreditCardValues = {
  number: "",
  expiry: "",
  securityCode: "",
  name: ""
};

const CreditCardInputContext = createContext<CreditCardInputContextValue>({
  values: EMPTY_VALUES,
  setValue: () => {}
});

const CreditCardInputFrame = styled(View, {
  displayName: "CreditCardInput",
  gap: "4xl"
});

const CreditCardInputGroup = createStyledHOC(
  CreditCardInputFrame,
  ({ children, ...props }, forwardedRef) => {
    const [values, setValues] = useState(EMPTY_VALUES);
    const setValue = useCallback((part: CreditCardPart, value: string) => {
      setValues(previous =>
        previous[part] === value ? previous : { ...previous, [part]: value }
      );
    }, []);

    const contextValue = useMemo(
      () => ({ values, setValue }),
      [values, setValue]
    );

    return (
      <CreditCardInputContext value={contextValue}>
        <CreditCardInputFrame ref={forwardedRef} {...props}>
          {children}
        </CreditCardInputFrame>
      </CreditCardInputContext>
    );
  },
  { displayName: "CreditCardInput" }
);

// Fades and scales the brand icon in on mount; keyed by brand so it replays
// when the brand changes. The object `transition` naming `enter` keeps a
// hover restyle mid-fade from snapping it, and `scale` needs a resting value
// to animate.
const CreditCardBrandIcon = styled(View, {
  displayName: "CreditCardBrandIcon",
  transition: { duration: "200ms", enter: "200ms" },
  opacity: "enter:0",
  scale: "1 enter:0.85",
  alignSelf: "stretch",
  justifyContent: "center",
  flexShrink: 0,
  paddingHorizontal: "2xl"
});

export type CreditCardInputPartProps = GetProps<typeof Input> & {
  placeholder?: string;

  /**
   * The security code only: milliseconds to show the last typed digit before
   * masking it, or `0` to mask it immediately.
   */
  delay?: number;
};

const createCreditCardPart = (
  part: CreditCardPart,
  rule: CreditCardPartRule,
  displayName: string
) =>
  createStyledHOC(
    Input,
    (
      {
        children,
        placeholder,
        delay = rule.passwordDelay,
        onInput,
        ...props
      }: CreditCardInputPartProps,
      forwardedRef
    ) => {
      const formControl = useFormControl();
      const { values, setValue } = use(CreditCardInputContext);

      // Inside a `Field`, the field holds the (parsed) value.
      const [localValue, setLocalValue] = useState("");
      const value = formControl ? String(formControl.value ?? "") : localValue;
      useEffect(() => setValue(part, value), [setValue, value]);

      const brand = getCreditCardBrand(
        part === "number" ? value : values.number
      );
      const mask = useMemo(() => rule.mask?.(brand), [brand]);

      // Inside a `Field`, the field's input ref applies the mask instead.
      const maskRef = useMaskito({
        options: formControl ? null : (mask ?? null)
      });

      const fieldOptions = useMemo(() => {
        const validator = (fieldValue: unknown, _: unknown, cause: string) => {
          const text = String(fieldValue ?? "");
          const message =
            text && (cause !== "change" || rule.isComplete(text, brand))
              ? rule.getError(text, brand)
              : undefined;

          return message
            ? [{ code: `credit-card-input.${part}`, message, type: "danger" }]
            : [];
        };

        return {
          defaults: {
            // Only the options this part has, so the field's own are kept.
            ...(mask && { mask }),
            ...(rule.parse && { parse: rule.parse }),
            ...(rule.format && { format: rule.format }),
            validate: { onChange: [validator], onBlur: [validator] }
          }
        };
      }, [brand, mask]);
      useFieldOptions(fieldOptions);

      const handleInput = useCallback<InputChangeEventHandler>(
        event => {
          setLocalValue(rule.parse?.(event.detail) ?? event.detail);
          onInput?.(event);
        },
        [onInput]
      );

      const password = rule.passwordDelay !== undefined;
      const Control = password ? PasswordInput : Input;

      return (
        <Control
          ref={forwardedRef}
          {...props}
          {...(password && { delay })}
          onInput={handleInput}>
          <Control.TextBox>
            <Control.TextBox.Value
              ref={maskRef}
              placeholder={placeholder}
              {...rule.valueProps}
            />
          </Control.TextBox>
          {rule.end?.(brand)}
          {children}
        </Control>
      );
    },
    { displayName }
  );

const CreditCardInputNumber = createCreditCardPart(
  "number",
  {
    mask: () => CARD_NUMBER_MASK,
    parse: toDigits,
    format: value => {
      const digits = toDigits(value);

      return groupDigits(digits, getCreditCardBrand(digits).groups);
    },
    isComplete: (digits, brand) => digits.length >= Math.max(...brand.lengths),
    getError: (digits, brand) => {
      if (!brand.lengths.includes(digits.length)) {
        return "Card number is incomplete";
      }
      if (!isLuhnValid(digits)) {
        return "Card number is invalid";
      }

      return undefined;
    },
    valueProps: { autoComplete: "cc-number", inputMode: "numeric" },
    end: brand =>
      brand.icon ? (
        <>
          <Input.Separator />
          <CreditCardBrandIcon key={brand.name}>
            <brand.icon height="62%" />
          </CreditCardBrandIcon>
        </>
      ) : null
  },
  "CreditCardInputNumber"
);

const CreditCardInputExpiry = createCreditCardPart(
  "expiry",
  {
    mask: () => EXPIRY_MASK,
    isComplete: value => value.length >= 5,
    getError: value => {
      const [, month, year] = /^(\d\d)\/(\d\d)$/.exec(value) ?? [];
      if (!month || !year) {
        return "Expiry date is incomplete";
      }

      if (Number(month) < 1 || Number(month) > 12) {
        return "Expiry month is invalid";
      }

      // A card is valid through the last day of its expiry month, so it
      // expires when the following month (`month` as a 0-based index) begins.
      if (new Date(2000 + Number(year), Number(month)) <= new Date()) {
        return "Card has expired";
      }

      return undefined;
    },
    valueProps: { autoComplete: "cc-exp", inputMode: "numeric" }
  },
  "CreditCardInputExpiry"
);

const CreditCardInputSecurityCode = createCreditCardPart(
  "securityCode",
  {
    mask: brand => ({
      mask: new RegExp(`^\\d{0,${brand.securityCodeLength}}$`)
    }),
    isComplete: (value, brand) => value.length >= brand.securityCodeLength,
    getError: (value, brand) =>
      value.length === brand.securityCodeLength
        ? undefined
        : `Security code must be ${brand.securityCodeLength} digits`,
    valueProps: { autoComplete: "cc-csc", inputMode: "numeric" },
    passwordDelay: 500
  },
  "CreditCardInputSecurityCode"
);

const CreditCardInputName = createCreditCardPart(
  "name",
  {
    isComplete: () => true,
    getError: value =>
      value.trim() ? undefined : "Enter the name shown on the card",
    valueProps: { autoComplete: "cc-name" }
  },
  "CreditCardInputName"
);

